using System.Diagnostics;
using System.IO;
using System.Text.Json;
using System.Windows;
namespace MacDock;
internal static class DockMotionChecks
{
    internal static async Task Run(Controller c)
    {
        var output=Environment.GetEnvironmentVariable("MACDOCK_TEST_RESULTS")!;Directory.CreateDirectory(output);var records=new List<object>();var frames=new List<object>();var phases=new List<double>();var times=Stopwatch.StartNew();Native.GetCursorPos(out var prior);PointerHook.NonInjectedInputs=0;PointerHook.AuditInput=true;
        void Check(string name,bool pass,object? detail=null){records.Add(new{name,pass,detail});File.WriteAllText(Path.Combine(output,"motion-progress.json"),JsonSerializer.Serialize(records));if(!pass)throw new Exception(name);}
        var fixture=new Window{Title="MacDock motion click fixture",Width=260,Height=120,Left=30,Top=60};DockMotion? nested=null;
        try{
            foreach(var e in c.Store.Data.Entries)e.Pinned=false;foreach(var e in c.Store.Data.Entries.Where(e=>e.InDrawer).Take(5))e.Pinned=true;c.Store.Add(Environment.ProcessPath!,true,"动画点击验收");c.Changed();fixture.Show();await Task.Delay(200);
            var area=c.WorkArea;int x=area.Left+area.Width/2,y=area.Bottom-(int)(12*c.Scale*c.Layout.Unit);Native.MovePointer(x,area.Top+250);await Task.Delay(650);
            c.DockAnimationFrame=(p,v)=>{Native.GetWindowRect(c.Dock.Handle,out var r);var shape=DockMotion.Shape(c.Dock.ActualWidth,c.Dock.ActualHeight,c.Dock.MaterialRadius,p);phases.Add(p);frames.Add(new{ms=times.Elapsed.TotalMilliseconds,p,v,x=r.Left,y=r.Top,shape=shape.Bounds.ToString(),c.Dock.RevealPhase});};
            Native.MovePointer(x,y);await Task.Delay(600);Check("real pointer wake completes finite sheet reveal",c.Dock.IsVisible&&!c.DockMotionRunning&&c.Dock.RevealPhase==1);Check("sheet changes both width and height with bounded spring",phases.Any(p=>p>.1&&p<.8)&&phases.Max()<1.025&&phases.Max()>1);
            bool flipped=false;var completions=new List<(bool Open,double Value,bool Running)>();nested=new DockMotion(p=>{if(p==1&&!flipped){flipped=true;nested!.To(false);}},open=>completions.Add((open,nested!.Value,nested.Running)));nested.Snap(0);nested.To(true);await Task.Delay(650);Check("retarget during rendering cannot emit stale completion",flipped&&completions.Count==1&&!completions[0].Open&&completions[0].Value==0&&!completions[0].Running,completions.Select(v=>new{v.Open,v.Value,v.Running}).ToArray());
            var first=c.Store.PinnedEntries()[0];var a=c.Dock.TileCenter(first.Id);Native.GetWindowRect(c.Dock.Handle,out var anchor);var order=c.Store.PinnedEntries().Select(e=>e.Id).ToArray();
            for(int i=0;i<6;i++){
                c.Collapse();await Task.Delay(65);var value=c.DockProgress;var speed=c.DockVelocity;c.Expand();Check("reverse retains current position and velocity "+i,Math.Abs(c.DockProgress-value)<.000001&&Math.Abs(c.DockVelocity-speed)<.000001);await Task.Delay(60);c.Collapse();await Task.Delay(45);c.Expand();await Task.Delay(400);Check("rapid reversal reaches one stable geometry "+i,c.Dock.IsVisible&&!c.DockMotionRunning&&Math.Abs(c.DockProgress-1)<.0001,new{c.DockProgress,c.DockVelocity,c.DockMotionRunning,visible=c.Dock.IsVisible,c.Diagnostics,input=PointerHook.NonInjectedInputs});Native.GetWindowRect(c.Dock.Handle,out var now);Check("native hit window anchor does not slide during reveal "+i,anchor.Left==now.Left&&anchor.Top==now.Top&&anchor.Right==now.Right&&anchor.Bottom==now.Bottom);
            }
            Check("reveal never changes pin order or overlaps slots",order.SequenceEqual(c.Store.PinnedEntries().Select(e=>e.Id))&&c.Dock.ArtworkBounds.Select(r=>Math.Round(r.X)).Distinct().Count()==order.Length);
            c.Store.Data.ReducedMotion=true;c.Changed();c.Collapse();Check("reduced motion hides immediately without clocks",!c.Dock.IsVisible&&!c.DockMotionRunning);c.Expand();Check("reduced motion opens at exact full geometry",c.Dock.IsVisible&&c.Dock.RevealPhase==1&&!c.DockMotionRunning);c.Store.Data.ReducedMotion=false;c.Changed();await Task.Delay(100);
            var opens=c.Dock.TipOpens;for(int n=0;n<4;n++)foreach(var entry in c.Store.PinnedEntries()){var p=c.Dock.TileCenter(entry.Id);Native.MovePointer(p.X,p.Y);await Task.Delay(60);}Check("fast horizontal sweeps never show names",!c.Dock.TipVisible&&c.Dock.TipOpens==opens);
            a=c.Dock.TileCenter(first.Id);Native.MovePointer(a.X,a.Y);await Task.Delay(720);Check("same tile has no early label",!c.Dock.TipVisible);Native.MovePointer(a.X+2,a.Y);await Task.Delay(420);Check("stable same slot shows after about one second",c.Dock.TipVisible&&c.Dock.TipEntryId==first.Id);Check("name is a visible native popup above Dock",c.Dock.TipHasNativeSurface);Native.GetWindowRect(c.Dock.Handle,out var labelBounds);using(var picture=new System.Drawing.Bitmap(labelBounds.Right-labelBounds.Left+80,labelBounds.Bottom-labelBounds.Top+120)){using(var graphics=System.Drawing.Graphics.FromImage(picture))graphics.CopyFromScreen(labelBounds.Left-40,labelBounds.Top-100,0,0,picture.Size);picture.Save(Path.Combine(output,"tip-actual.png"));}opens=c.Dock.TipOpens;for(int n=0;n<5;n++){Native.MovePointer(a.X+(n%2==0?2:-2),a.Y);await Task.Delay(70);}Check("magnification and small moves do not flicker or restart label",c.Dock.TipVisible&&c.Dock.TipOpens==opens&&c.Dock.MaxScale>1.1);
            var oldTip=c.Dock.TipWindowHandle;var next=c.Store.PinnedEntries()[1];var b=c.Dock.TileCenter(next.Id);Native.MovePointer(b.X,b.Y);await Task.Delay(80);Check("switching tile hides native tooltip HWND promptly",oldTip!=0&&!Native.IsWindowVisible(oldTip));await Task.Delay(80);Check("switching tile closes previous label immediately",!c.Dock.TipVisible);await Task.Delay(650);Check("switching never inherits accelerated tooltip delay",!c.Dock.TipVisible);await Task.Delay(300);Check("second tile has its own full dwell",c.Dock.TipVisible&&c.Dock.TipEntryId==next.Id);
            Native.TestButton(true);await Task.Delay(60);Check("pointer down cancels visible name before drag",!c.Dock.TipVisible);Native.MovePointer(b.X+12,b.Y);await Task.Delay(120);Check("drag starts normally and suppresses label",PointerSort.Active!=null&&!c.Dock.TipVisible);Native.TestKey(27,true);await Task.Delay(90);Native.TestKey(27,false);Native.TestButton(false);await Task.Delay(200);Check("canceled drag retains order without stale capture",PointerSort.Active==null&&!c.InternalDragging&&order.SequenceEqual(c.Store.PinnedEntries().Select(e=>e.Id)));
            Native.MovePointer(x,area.Top+250);await Task.Delay(650);Check("collapse cancels hints and all motion timers",!c.Dock.IsVisible&&!c.Dock.TipVisible&&!c.DockMotionRunning&&Anim.ActiveTimers==0);
            Native.MovePointer(x,y);await Task.Delay(600);c.ToggleDrawer();await Task.Delay(450);var tiles=c.Drawer!.SortTiles(false);Check("drawer still has no name tooltip and retains accessible names",tiles.All(t=>t.ToolTip==null&&!string.IsNullOrWhiteSpace(System.Windows.Automation.AutomationProperties.GetName(t))));a=c.Dock.TileCenter(first.Id);Native.MovePointer(a.X,a.Y);await Task.Delay(380);Check("open drawer still permits normal Dock wave",c.Dock.MaxScale>1.1);c.CloseDrawer(keepDock:true);await Task.Delay(300);
            var test=c.Store.Data.Entries.Single(e=>e.Path==Environment.ProcessPath);Native.MovePointer(x,area.Top+250);c.Collapse();await Task.Delay(500);Native.MovePointer(x,y);await Task.Delay(150);var at=c.Dock.TileCenter(test.Id);var launches=c.LaunchCount;Native.MovePointer(at.X,at.Y);Native.TestButton(true);await Task.Delay(50);Native.TestButton(false);await Task.Delay(200);Check("click during entrance settles then switches exactly once",c.LaunchCount==launches+1&&!c.Dock.TipVisible&&PointerSort.Active==null);
            Native.MovePointer(x,area.Top+250);await Task.Delay(650);Check("final no residual rendering or animation clocks",!c.Dock.WaveRunning&&!c.DockMotionRunning&&Anim.ActiveTimers==0);Check("no concurrent physical mouse input",PointerHook.NonInjectedInputs==0);
        }catch(Exception e){records.Add(new{name="error",pass=false,detail=(object)e.ToString()});}
        finally{nested?.Cancel();c.DockAnimationFrame=null;PointerSort.Active?.End(false);Native.TestButton(false);PointerHook.AuditInput=false;fixture.Close();if(PointerHook.NonInjectedInputs==0)Native.MovePointer(prior.X,prior.Y);File.WriteAllText(Path.Combine(output,"dock-motion.json"),JsonSerializer.Serialize(records,new JsonSerializerOptions{WriteIndented=true}));File.WriteAllText(Path.Combine(output,"dock-motion-frames.json"),JsonSerializer.Serialize(frames));System.Windows.Application.Current.Shutdown();}
    }
}
